set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import hashlib,importlib.metadata,json,shutil
assert importlib.metadata.version('langgraph')=='1.2.14'
manifest=json.loads(Path('rag/eval/baselines/mixed_v1/manifest.json').read_text())
for filename in ('rag/service/mixed_service.py','rag/service/ticket_service.py','rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/service/answer_service.py','rag/retrieval/search_chunks.py'):
    assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==manifest['file_sha256'][filename],filename
backup=Path('deploy/backups/langgraph-2026-10-12');backup.mkdir(parents=True,exist_ok=False)
shutil.copyfile('rag/service/retrieval_server.py',backup/'retrieval_server.py')
(backup/'manifest.json').write_text(json.dumps({'prior_graph_flag':'0','no_secrets_archived':True,'langgraph_version':'1.2.14','unit_tests_passed':50}))
for filename in ('ask_graph.py','graph_tools.py','retrieval_server.py'):
    shutil.copyfile(Path('/tmp/travel-graph-stage-20261012/service')/filename,Path('rag/service')/filename)
shutil.copyfile('/tmp/travel-graph-stage-20261012/eval/test_ask_graph.py','rag/eval/test_ask_graph.py')
p=Path('.env');lines=[line for line in p.read_text().splitlines() if not line.startswith('RAG_LANGGRAPH_ENABLED=')]
lines.append('RAG_LANGGRAPH_ENABLED=1');p.write_text('\n'.join(lines)+'\n')
print('LangGraph enabled; frozen mixed, SQL, classifiers, prompt and retrieval untouched')
PY
